const S={topic:catalogQuery.get('topic')||'all',sort:['recent','title','topic'].includes(catalogQuery.get('sort'))?catalogQuery.get('sort'):'topic',subject:['physics','math'].includes(catalogQuery.get('subject'))?catalogQuery.get('subject'):'all',navMode:catalogPrefs.navMode==='topics'?'topics':'folders',introHidden:catalogPrefs.introHidden===true,expanded:new Set(Array.isArray(catalogPrefs.expanded)?catalogPrefs.expanded.filter(id=>typeof id==='string').slice(0,512):['gallery_physics','gallery_math','topics:physics','topics:math','topics:other']),saveError:'',previewError:'',validationError:'',library:{models:[],folders:[]},folder:catalogQuery.get('folder')||'all',search:catalogQuery.get('search')||'',grade:['8','10'].includes(catalogQuery.get('grade'))?catalogQuery.get('grade'):'all',view:'catalog',draft:null,record:null,folderId:null,selection:null,tab:'object',sceneTool:'select',dirty:false,present:false,running:false,speed:1,sim:null,history:[],error:'',undo:[],redo:[],busy:false};
const icons={chevronRight:'M9 5l7 7-7 7',chevronDown:'M5 9l7 7 7-7',plus:'M12 5v14M5 12h14',folder:'M3 7h6l2-3h4l2 3h4v13H3z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',back:'M15 5l-7 7 7 7',play:'M8 4l12 8-12 8z',pause:'M7 4v16M17 4v16',reset:'M3 10a9 9 0 1 1 2 9M3 3v7h7',step:'M5 4l12 8-12 8zM20 4v16',save:'M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',upload:'M12 16V3M7 8l5-5 5 5M4 17v4h16v-4',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',copy:'M8 8h13v13H8zM3 16V3h13',edit:'M4 16l12-12 4 4L8 20H4z',book:'M4 3h16v18H4zM8 3v18M11 7h5M11 11h5',help:'M9 8a3 3 0 1 1 4 3l-1 2M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',refresh:'M3 10a9 9 0 0 1 15-6l3 3M21 2v5h-5M21 14a9 9 0 0 1-15 6l-3-3M3 22v-5h5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',close:'M6 6l12 12M6 18L18 6',more:'M5 12h.01M12 12h.01M19 12h.01',undo:'M9 5L3 11l6 6M3 11h12a6 6 0 0 1 6 6',redo:'M15 5l6 6-6 6M21 11H9a6 6 0 0 0-6 6'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]??icons.grid}"/></svg>`;
const button=(action,label,kind='',symbol='')=>`<button type="button" class="btn ${kind}" data-a="${action}" ${action==='save'&&S.busy?'disabled':''}>${symbol?icon(symbol):''}${label}</button>`;
const ib=(action,symbol,title)=>`<button class="icon-btn" data-a="${action}" ${(action==='undo'&&!S.undo.length)||(action==='redo'&&!S.redo.length)?'disabled':''} title="${esc(title)}" aria-label="${esc(title)}">${icon(symbol)}</button>`;
const field=(label,key,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input type="${type}" aria-label="${esc(label)}" data-field="${key}" value="${esc(value)}" ${type==='number'?'step="any"':''} ${extra}></label>`;
const select=(label,key,value,options)=>`<label class="field"><span>${label}</span><select aria-label="${esc(label)}" data-field="${key}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const check=(label,key,value)=>`<label class="check"><input type="checkbox" data-field="${key}" ${value?'checked':''}>${label}</label>`;
const unique=(prefix,items)=>{const all=[...items,...(S.draft?.bodies??[]),...(S.draft?.parameters??[]),...(S.draft?.quantities??[]),...(S.draft?.graphs??[]),...(S.draft?.connections??[]),...(S.draft?.fields??[])];let i=1;while(all.some(o=>o.id===prefix+i)||reservedNames.has(prefix+i))i++;return prefix+i;};
const fileName=title=>title.replace(/[<>:"/\\|?*]/g,'_').slice(0,80)||'модель';
function toast(message,error=false){const t=document.querySelector('#toast');t.textContent=message;t.className='show'+(error?' bad':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',5000);}
async function api(action){const r=await fetch('/api/library',action?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action)}:{});const data=await r.json();if(!r.ok){const error=new Error(data.error||'Не удалось выполнить действие');error.status=r.status;throw error;}return action?data.result:data;}
async function refresh(silent=false){try{S.library=await api();if(!silent)render();return true;}catch(e){toast(e.message,true);if(!silent)app.innerHTML=`<div class="load-error"><h1>Каталог недоступен</h1><p>${esc(e.message)}</p>${button('refresh','Попробовать ещё раз','primary','refresh')}</div>`;return false;}}
function folderOptions(selected,rootLabel='Без папки'){return `<option value="">${rootLabel}</option>`+folderTree().map(f=>`<option value="${f.id}" ${f.id===selected?'selected':''}>${'— '.repeat(f.depth)}${esc(f.name)}</option>`).join('');}
function folderTree(){const out=[];function visit(parent,depth){for(const f of S.library.folders.filter(f=>f.parentId===parent)){out.push({...f,depth});visit(f.id,depth+1);}}visit(null,0);return out;}
function descendants(id){const ids=new Set([id]);let changed=true;while(changed){changed=false;for(const f of S.library.folders)if(ids.has(f.parentId)&&!ids.has(f.id)){ids.add(f.id);changed=true;}}return ids;}
function visibleModels(){return catalogModels(S.library,S);}
function catalog(){const models=visibleModels(),selected=S.library.folders.find(f=>f.id===S.folder);return `<div class="workspace" data-panel-shell><aside class="sidebar ${S.mobileNav?'mobile-nav-open':'mobile-nav-collapsed'}"><a class="brand" href="/" aria-label="Модельная"><span class="brand-mark">М</span><span>Модельная<small>Физика и математика</small></span></a><button class="mobile-nav-toggle" data-a="mobile-nav" aria-expanded="${!!S.mobileNav}">${icon(S.mobileNav?'chevronDown':'chevronRight')}Папки и темы</button><button class="nav-item ${S.folder==='all'?'active':''}" data-folder="all">${icon('grid')}Все модели<span>${S.library.models.filter(m=>!m.archived).length}</span></button><div class="nav-label">КАТАЛОГ${ib('new-folder','plus','Создать папку')}</div><div class="nav-modes"><button data-nav-mode="folders" class="${S.navMode==='folders'?'selected':''}">Разделы</button><button data-nav-mode="topics" class="${S.navMode==='topics'?'selected':''}">Темы</button></div><nav class="folder-navigation" aria-label="${S.navMode==='folders'?'Разделы':'Темы моделей'}">${S.navMode==='folders'?sidebarFolders(S,icon):sidebarTopics(S,icon)}</nav><div class="sidebar-bottom"><button class="nav-item ${S.folder==='trash'?'active':''}" data-folder="trash">${icon('trash')}Корзина</button><button class="nav-item" data-a="help">${icon('help')}Как пользоваться</button><div class="local-note">Каталог на этом компьютере</div></div>${panelHandle('catalog','Ширина панели каталога')}</aside><main class="catalog"><header class="catalog-top"><span>Рабочее пространство <span class="slash">/</span> Каталог</span><div>${themePicker()}${ib('refresh','refresh','Обновить каталог')}${button('standalone-analysis','Анализ данных','quiet','grid')}${button('backup','Резервная копия','quiet','download')}${button('import','Импорт','quiet','upload')}${button('new-model','Новая модель','primary','plus')}</div></header><section class="catalog-content">${breadcrumbs(S)}<div class="heading-row"><div><h1>${selected?esc(selected.name):S.folder==='trash'?'Корзина':S.topic!=='all'?esc(S.topic):'Модели'}</h1>${S.folder==='trash'?'<p>Удалённые модели можно восстановить.</p>':''}</div>${selected?`<div class="folder-actions">${ib('rename-folder','edit','Переименовать папку')}${ib('delete-folder','trash','Удалить пустую папку')}</div>`:''}</div>${publicIntro()}<div class="filter-row"><label class="search">${icon('search')}<input id="search" placeholder="Волны, геометрия, вероятность…" value="${esc(S.search)}" aria-label="Поиск моделей"></label><div class="segments" aria-label="Предмет"><button data-subject="all" class="${S.subject==='all'?'selected':''}">Все</button><button data-subject="physics" class="${S.subject==='physics'?'selected':''}">Физика</button><button data-subject="math" class="${S.subject==='math'?'selected':''}">Математика</button></div></div>${catalogFilters(S,plural)}<div id="model-grid" class="${S.sort==='topic'?'grouped-models':'model-grid'}">${groupedCards(models,S,cards)}</div></section><footer class="catalog-footer"><span>Модельная / 2.4.0 · черновик</span></footer></main></div>`;}
function publicIntro(){
 if(S.folder!=='all'||S.topic!=='all'||S.search||S.subject!=='all')return '';
 if(S.introHidden)return '<div class="intro-restore"><button type="button" class="text-btn" data-a="show-intro">'+icon('book')+'Показать быстрый старт</button></div>';
 return '<section class="public-intro" aria-label="Быстрый старт"><header class="public-intro-heading"><strong>Первый опыт — за минуту</strong><button type="button" class="text-btn" data-a="hide-intro" aria-label="Скрыть быстрый старт">'+icon('close',16)+'Скрыть</button></header><div class="public-intro-content"><div><a href="/guide.html" target="_blank" rel="noopener">Руководство пользователя ↗</a></div><div class="starter-picks"><button class="btn quiet" data-open="gallery_circle">Синус и косинус</button><button class="btn quiet" data-open="gallery_electromagnetic_wave">Электромагнитная волна</button><button class="btn quiet" data-open="gallery_monte_carlo">Случайность и π</button></div></div></section>';
}
function plural(n){return n%10===1&&n%100!==11?'модель':n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?'модели':'моделей';}
function cards(models){return models.length?models.map(m=>`<article class="model-card"><button class="card-preview" data-open="${m.id}" aria-label="Открыть ${esc(m.spec.title)}">${m.spec.kind==='html'?htmlThumbnail(m.spec):preview(m.spec)}<span class="subject-badge ${m.spec.subject==='math'?'math':''}">${m.spec.subject==='math'?'Математика':'Физика'}</span><span class="preview-open">${icon('eye')}Начать опыт</span></button><div class="card-content"><button class="card-topic" data-topic="${esc(modelTopic(m.spec))}">${esc(modelTopic(m.spec))}</button><button class="card-title" data-open="${m.id}">${esc(m.spec.title)}</button><p>${esc(m.spec.description||'Авторская модель')}</p><div class="card-footer"><span>${m.spec.kind==='html'?'Готовая демонстрация':`Конструктор · ${m.spec.bodies.length} ${m.spec.bodies.length===1?'объект':'объекта'} · ${m.spec.parameters.length} параметра`}</span><button class="icon-btn" data-card-menu="${m.id}" title="Действия с моделью" aria-label="Действия с ${esc(m.spec.title)}">${icon('more')}</button></div></div></article>`).join(''):`<div class="empty"><span>${icon('folder',36)}</span><h2>${S.search||S.topic!=='all'||S.grade!=='all'?'По этим условиям моделей нет':'Здесь пока нет моделей'}</h2><p>${S.search||S.topic!=='all'||S.grade!=='all'?'Измените тему, класс или поисковый запрос.':'Создайте модель с пустой сцены или импортируйте файл.'}</p>${S.search||S.topic!=='all'||S.grade!=='all'?button('reset-filters','Сбросить фильтры','quiet'):''}${S.folder==='trash'?'':button('new-model','Создать модель','primary','plus')}</div>`;}
const teaching=initTeaching(S,{dialog,button,render,pushUndo,changed,api,toast,captureControls,applySavedControls,saveDraft,updateScene,resetSimulation,closeDialog});
const dataAnalysis=initAnalysis(S,{document,dialog,render,pushUndo,changed,save,toast,download});
async function openAnalysisWorkspace(){
 dataAnalysis.reset();S.analysisStandalone=true;S.view='analysis';S.tab='data';S.running=false;S.dirty=false;S.present=false;S.record=null;S.draft=emptyModel();S.draft.title='Анализ данных';S.undo=[];S.redo=[];
 history.replaceState(null,'','/?analysis=1');render();window.scrollTo?.(0,0);await dataAnalysis.loadStandalone();
}
function analysisWorkspace(){return `<div class="analysis-standalone"><header class="editor-header"><div class="editor-identity">${ib('back','back','Вернуться в каталог')}<span class="brand-mark small">М</span><strong>Анализ данных</strong></div><div class="editor-actions">${themePicker()}</div></header><main class="analysis-workspace">${dataAnalysis.panel()}</main></div>`;}
function editor(){const m=S.draft;if(m.kind==='html')return htmlEditor(S,{icon,ib,button,field,select,folderOptions,themePicker,topicField,editorFeedback,teachingBar});return `<div class="editor-shell ${S.tab==='data'?'analysis-mode':''} ${S.present?'present':''}" data-panel-shell><header class="editor-header"><div class="editor-identity">${ib('back','back','Вернуться в каталог')}<span class="brand-mark small">М</span><div><strong>${esc(m.title)}</strong><small id="save-state">${S.experimentOnly?'Параметры текущего опыта · без сохранения':S.dirty?'Есть несохранённые изменения':'Сохранено в каталоге'}</small></div></div><div class="editor-actions">${themePicker()}${ib('undo','undo','Отменить')}${ib('redo','redo','Повторить')}${button('export','Экспорт','quiet','download')}${S.present?button('analysis-open','Данные','quiet','grid'):''}${button('present',S.present?'Редактор':'Показ на уроке','quiet','eye')}${S.present?'':button('save',S.busy?'Сохраняем…':'Сохранить','primary','save')}</div></header>${editorFeedback(S)}<div id="teaching-kit">${teachingBar(S)}</div><div class="editor-main"><aside class="object-panel"><div class="panel-heading"><h2>Состав модели</h2>${ib('add-body','plus','Добавить объект')}</div><div class="object-list">${m.bodies.map(b=>`<button data-select-body="${b.id}" class="object-item ${S.selection===b.id&&S.tab==='object'?'selected':''}"><span class="shape-symbol ${b.shape}" data-charge-sign="${(b.charge??0)>0?'+':(b.charge??0)<0?'−':'0'}" style="--object-color:${b.color}"></span><span>${esc(b.name)}<small>${b.motion==='force'?'Действие сил':b.motion==='formula'?'Движение по формуле':'Неподвижный объект'}</small></span></button>`).join('')||'<p class="muted-pad">Начните с объекта. Его положение и поведение можно изменить.</p>'}</div>${componentList(m,'connections',S.selection,icon)}${componentList(m,'fields',S.selection,icon)}<div class="panel-divider"></div><div class="tools-nav">${[['connections','Связи',m.connections?.length??0],['fields','Поля',m.fields?.length??0],['parameters','Параметры',m.parameters.length],['quantities','Величины',m.quantities.length],['graphs','Графики',m.graphs.length],['data','Данные',m.analysis?.datasets[0]?.rows.length??''],['settings','Модель и урок','']].map(([tab,label,count])=>`<button class="tool-tab ${S.tab===tab?'selected':''}" data-tab="${tab}">${tab==='settings'?icon('book'):tab==='graphs'?'<span class="mini-chart">∿</span>':tab==='parameters'?'<span class="mini-chart">≡</span>':'<span class="mini-chart">ƒ</span>'}${label}<small>${count}</small></button>`).join('')}</div><div class="object-bottom">${button('add-connection','Добавить связь','quiet full','plus')}${button('add-field','Добавить поле','quiet full','plus')}<button class="text-btn" data-a="help">Справочник формул</button></div>${panelHandle('objects','Ширина списка объектов')}</aside><main class="simulation ${S.tab==='data'?'analysis-workspace':''}">${dataAnalysis.panel()}<section class="scene-pane"><div class="stage-heading"><span>СЦЕНА</span><div><span class="time" id="stage-time">t = 0 с</span>${ib('reset','reset','Вернуть начальные условия')}</div></div>${sceneToolbar()}${fieldLayerControls()}<button class="properties-jump text-btn" data-a="show-properties">Свойства и настройки ↓</button>${S.comparison?'<p class="comparison-caption">Опыт A · текущие параметры &nbsp; / &nbsp; Опыт B · выбранные параметры</p>':''}<div class="scene-pair ${S.comparison?'comparing':''}"><section class="experiment-view">${S.comparison?`<div class="experiment-label"><b>Опыт A</b>${m.parameters.map(p=>`<span>${esc(p.label)}: ${fmt(p.value)} ${esc(p.unit)}</span>`).join('')}</div>`:''}<div id="scene" class="scene" tabindex="0" aria-label="Координатная плоскость. Перемещение перетаскиванием, масштаб кнопками или колесом." style="touch-action:none"></div></section>${S.comparison?`<section class="experiment-view"><div class="experiment-label"><b>Опыт B</b>${S.comparison.model.parameters.map(p=>`<span>${esc(p.label)}: ${fmt(p.value)} ${esc(p.unit)}</span>`).join('')}</div><div id="comparison-scene" class="scene" aria-label="Опыт B · те же оси и масштаб"></div></section>`:''}</div>${S.comparison?'<div id="comparison-values" class="comparison-values"></div>':''}<p class="scene-hint">${S.present?'Перетаскивайте плоскость; колесо меняет масштаб.':'Колесо — масштаб. Пустое место или «Переместить» — сдвиг плоскости. Объект — изменение начального положения.'}</p><div class="transport"><div>${ib('reset','reset','Сброс')}${button('play',S.running?'Пауза':'Запустить','play-btn primary',S.running?'pause':'play')}${ib('step','step','Один шаг')}</div><div><select id="speed" aria-label="Скорость показа">${[...new Set([.25,.5,1,2,S.speed])].sort((a,b)=>a-b).map(v=>`<option value="${v}" ${v===S.speed?'selected':''}>${fmt(v)}×</option>`).join('')}</select><span class="duration">${fmt(m.duration)} с</span></div></div><div id="sim-error" role="alert" class="sim-error"></div></section><section class="controls-pane"><div id="live-controls" class="live-controls">${liveControls()}</div><div id="quantities" class="quantity-row"></div>${S.comparison?'<div id="comparison-graphs"></div>':''}<div id="graphs" class="graphs"></div>${m.notes?`<div class="lesson-note"><span>${icon('book')}</span><div><strong>К занятию</strong><p>${esc(m.notes).replaceAll('\n','<br>')}</p></div></div>`:''}</section></main><aside class="inspector"><div class="panel-heading"><h2>${S.tab==='object'?'Свойства объекта':S.tab==='connections'?'Свойства связи':S.tab==='fields'?'Свойства поля':S.tab==='parameters'?'Параметры':S.tab==='quantities'?'Измеряемые величины':S.tab==='graphs'?'Графики':'Модель и урок'}</h2></div><div class="inspector-content">${inspector()}</div>${panelHandle('properties','Ширина свойств модели')}</aside></div></div>`;}
function sceneToolbar(){return `<div class="scene-toolbar" role="toolbar" aria-label="Вид координатной плоскости"><div><button data-a="scene-select" class="${S.sceneTool==='select'?'active':''}" aria-pressed="${S.sceneTool==='select'}">Выбрать</button><button data-a="scene-pan" class="${S.sceneTool==='pan'?'active':''}" aria-pressed="${S.sceneTool==='pan'}">Переместить</button></div><div><button data-a="zoom-out" aria-label="Отдалить плоскость">−</button><output id="view-scale">${Math.round(cameraOf(S.draft.scene).zoom*100)}%</output><button data-a="zoom-in" aria-label="Приблизить плоскость">+</button><button data-a="reset-view">Исходный вид</button></div></div>`;}
function changeView(camera,remember=true){if(remember)pushUndo();S.draft.scene.camera=camera;S.dirty=true;saveDraft();updateScene();updateEditorChrome();}
function fieldLayerControls(){const m=S.draft,relevant=key=>!S.present||(key==='electric'?m.bodies.some(b=>(b.charge??0)!==0&&b.fieldEnabled!==false):key==='gravity'?m.bodies.some(b=>b.gravityEnabled):false)||(m.fields??[]).some(f=>f.enabled&&f.show&&(key==='electric'?f.type==='electric':key==='gravity'?f.type==='gravity':f.type.startsWith('magnetic')));const layers=[['electric','Потенциал φ'],['gravity','Потенциал Φg'],['magnetic','Карта Bz']].filter(([key])=>relevant(key));if(!layers.length)return '';return '<div class="field-layer-controls" aria-label="Отображение полей">'+layers.map(([key,label])=>'<label class="check"><input type="checkbox" data-field-layer="'+key+'" '+(fieldLayerEnabled(m,key)?'checked':'')+'>'+label+'</label>').join('')+'</div>'+(S.present?'':'<details class="field-map-help"><summary>Что показывают карты поля</summary><p class="field-map-hint">Карты включают глобальные поля; поля с выборочными целями задают отдельные правила сил.</p></details>');}
function liveControls(){return S.draft.parameters.map(p=>`<label class="live-param"><span>${esc(p.label)}<strong id="value-${p.id}">${fmt(p.value)} ${esc(p.unit)}</strong></span><input type="range" min="${p.min}" max="${p.max}" step="any" value="${p.value}" data-live="${p.id}" aria-label="${esc(p.label)}"><small>${fmt(p.min)}<span>${fmt(p.max)} ${esc(p.unit)}</span></small></label>`).join('')+`<div class="charge-switches">${S.draft.bodies.filter(b=>(b.charge??0)!==0).map(b=>`<label class="check charge-source-toggle"><input type="checkbox" data-charge-source="${b.id}" ${b.fieldEnabled!==false?'checked':''}>Поле частицы: ${esc(b.name)}</label>`).join('')}</div>`;}
function inspector(){const m=S.draft;if(['connections','fields'].includes(S.tab))return componentsInspector(m,S.tab,S.selection,{field,select,check,button,icon,section:(id,title,content,options)=>propertySection(inspectorScope(),id,title,content,options)});if(S.tab==='object'){const b=m.bodies.find(b=>b.id===S.selection);if(!b)return `<div class="inspector-empty"><p>Выберите объект на сцене или добавьте новый.</p>${button('add-body','Добавить объект','primary','plus')}</div>`;
 return bodyInspector(m,b,inspectorScope(),{field,select,check,button});
 }
 if(S.tab==='parameters')return `<p class="hint intro">Создайте величину и используйте её имя в формулах. Ползунок появится под сценой.</p>${m.parameters.map((p,i)=>`<div class="editable-group"><div class="group-title"><b>${esc(p.label)}</b><button class="icon-btn" data-remove="parameters:${i}" aria-label="Удалить параметр">${icon('trash',16)}</button></div>${p.binding?`<p class="hint">Управляет ${esc(p.binding.body??p.binding.connection)} · ${esc(p.binding.property)}</p>${button('teach-unbind:'+p.id,'Отвязать от свойства','quiet')}`:''}${field('Подпись',`parameters.${i}.label`,p.label)}<div class="field-row">${field('Имя',`parameters.${i}.id`,p.id)}${field('Единица',`parameters.${i}.unit`,p.unit)}</div>${field('Значение',`parameters.${i}.value`,p.value,'number')}<div class="field-row">${field('Минимум',`parameters.${i}.min`,p.min,'number')}${field('Максимум',`parameters.${i}.max`,p.max,'number')}</div></div>`).join('')}${button('add-param','Добавить параметр','quiet full','plus')}`;
 if(S.tab==='quantities'||S.tab==='graphs'){const name=S.tab;return `<p class="hint intro">${name==='quantities'?'Результаты формул появятся как измерения.':'Графики показывают изменение величины во времени.'} Доступны параметры и координаты объектов: <code>b1_x</code>, <code>b1_vx</code>.</p>${m[name].map((q,i)=>`<div class="editable-group"><div class="group-title"><b>${esc(q.label)}</b><button class="icon-btn" data-remove="${name}:${i}" aria-label="Удалить">${icon('trash',16)}</button></div>${field('Подпись',`${name}.${i}.label`,q.label)}<div class="field-row">${field('Имя',`${name}.${i}.id`,q.id)}${field('Единица',`${name}.${i}.unit`,q.unit)}</div>${name==='graphs'?check('Подбирать масштаб автоматически',`${name}.${i}.autoScale`,q.autoScale!==false)+(q.autoScale===false?`<div class="field-row">${field('Минимум оси',`${name}.${i}.minY`,q.minY??0,'number')}${field('Максимум оси',`${name}.${i}.maxY`,q.maxY??1,'number')}</div><p class="hint">Масштаб остаётся постоянным. Значения за пределами оси обрезаются.</p>`:'<p class="hint">Диапазон оси меняется по данным. Для сравнения опытов отключите автоматический масштаб.</p>'):''}${field('Формула',`${name}.${i}.expression`,q.expression)}</div>`).join('')}${button(name==='quantities'?'add-quantity':'add-graph',name==='quantities'?'Добавить величину':'Добавить график','quiet full','plus')}<button class="text-btn" data-a="help">Какие формулы поддерживаются?</button>`;}
 const group=(id,title,content,options)=>propertySection(inspectorScope(),id,title,content,options);
 return group('about','Название и тема',field('Название','title',m.title)+field('Короткое описание','description',m.description)+topicField(m,allTopics(S.library)))+
 group('lesson','Урок и каталог',field('Урок','lesson',m.lesson)+'<div class="field-row">'+select('Предмет','subject',m.subject,[['physics','Физика'],['math','Математика']])+'</div><label class="field"><span>Папка в каталоге</span><select id="editor-folder">'+folderOptions(S.folderId)+'</select></label>')+
 group('notes','Пояснение и задание','<label class="field"><span>Текст для ученика</span><textarea data-field="notes" rows="5">'+esc(m.notes)+'</textarea></label>',{open:!!m.notes})+
 group('calculation','Время и точность расчёта',field('Длительность, с','duration',m.duration,'number','min="0.1" max="300"')+field('Шаг расчёта, с','dt',m.dt,'number','min="0.001" max="0.05"')+'<p class="hint">Меньший шаг повышает точность. Для быстрых пружин, магнитного поля, сопротивления и взаимодействия зарядов шаг автоматически дробится. Для произвольных сил по формуле точность нужно проверять отдельно.</p>',{open:false})+
 group('plane','Координатная плоскость','<div class="field-row">'+field('x минимум, м','scene.minX',m.scene.minX,'number')+field('x максимум, м','scene.maxX',m.scene.maxX,'number')+'</div><div class="field-row">'+field('y минимум, м','scene.minY',m.scene.minY,'number')+field('y максимум, м','scene.maxY',m.scene.maxY,'number')+'</div>'+check('Сетка на сцене','scene.grid',m.scene.grid)+'<p class="hint">Одинаковый масштаб по обеим осям. Приближение и сдвиг меняют только вид, а не положение объектов или время.</p>',{open:false})+
 '<p class="hint intro">Величины задаются в СИ. Размерности авторских формул автоматически не проверяются. Объекты — материальные точки; столкновения, физическое вращение и блоки с перекинутой нитью пока не рассчитываются.</p>';

}
function inspectorScope(){return (S.record?.id??'draft')+':'+S.tab+':'+(S.selection??'');}
function render(){S.fieldRenderPending=false;const oldInspector=app.querySelector('.inspector'),sameInspector=oldInspector?.dataset?.scope===inspectorScope(),inspectorScroll=sameInspector?oldInspector.scrollTop:0,active=document.activeElement,focusKey=sameInspector&&oldInspector?.contains?.(active)?active?.dataset?.field:null;const oldFrame=S.view==='editor'&&S.draft?.kind==='html'?document.querySelector('#html-frame'):null;const url=oldFrame?(S.previewHTML===S.draft.html?S.previewUrl:(S.record&&S.draft.html===S.record.spec.html?'/api/html/'+S.record.id:null)):null;if(oldFrame&&url&&oldFrame.getAttribute('src')===url&&(S.present||S.tab!=='source')){const shell=app.querySelector('.html-editor'),fresh=document.createElement('div');fresh.innerHTML=htmlEditor(S,{icon,ib,button,field,select,folderOptions,themePicker,topicField,editorFeedback,teachingBar});refreshHTMLChrome(shell,fresh);oldFrame.title=S.draft.title;}else app.innerHTML=S.view==='catalog'?catalog():S.view==='analysis'?analysisWorkspace():editor();initPanels(document);installSpeedInput(document);if(S.view==='analysis')dataAnalysis.mount();if(S.view==='editor'){updateScene();if(S.draft.kind!=='html'){bindNativeScene();const pane=app.querySelector('.inspector');if(pane){pane.dataset.scope=inspectorScope();bindInspectorSections(pane);if(sameInspector){pane.scrollTop=inspectorScroll;for(const input of pane.querySelectorAll('[data-field]'))if(input.dataset.field===focusKey){input.focus({preventScroll:true});break;}}}}updateEditorChrome();const shell=app.querySelector('.editor-shell');shell?.classList.toggle('results-hidden',false);if(S.dirty)saveDraft();dataAnalysis.mount();}}
function snapshot(){return {spec:structuredClone(S.draft),folderId:S.folderId};}
function historySnapshot(){const {analysis,...base}=S.draft,spec=structuredClone(base);if(analysis){spec.analysis=structuredClone({...analysis,datasets:[]});spec.analysis.datasets=analysis.datasets;}return {spec,folderId:S.folderId};}
function pushUndo(){S.undo.push(historySnapshot());if(S.undo.length>60)S.undo.shift();S.redo=[];}
function changed(){S.comparison=null;applyBindings(S.draft);S.dirty=true;S.running=false;S.saveError='';S.validationError='';try{validatePhysics(validateModel(S.draft));}catch(error){S.validationError=error.message;}resetSimulation();saveDraft();updateEditorChrome();}
function saveDraft(){if(S.experimentOnly)return;try{localStorage.setItem('model-studio-public-draft',JSON.stringify({id:S.record?.id,revision:S.record?.revision,...snapshot()}));}catch{}}
function resetSimulation(){S.running=false;S.error='';if(S.comparison){S.comparison.sim=initialState(S.comparison.model);S.comparison.history=[structuredClone(S.comparison.sim)];}if(S.draft.kind==='html'){S.sim=null;S.history=[];return;}try{S.sim=initialState(S.draft);S.history=[structuredClone(S.sim)];}catch(e){S.error=e.message;S.sim={t:0,bodies:Object.fromEntries(S.draft.bodies.map(b=>[b.id,{x:b.x,y:b.y,vx:b.vx,vy:b.vy}]))};S.history=[];}}
function updateScene(){if(S.view!=='editor')return;const m=S.draft;if(m.kind==='html'){const f=document.querySelector('#html-frame');if(f&&m.html!==S.record?.spec.html&&(S.previewHTML!==m.html||!S.previewUrl)){prepareHTMLPreview().then(()=>{if(S.view==='editor')updateScene();}).catch(e=>toast(e.message,true));}const url=S.previewHTML===m.html?S.previewUrl:(S.record&&m.html===S.record.spec.html?'/api/html/'+S.record.id:null);if(f&&url&&f.getAttribute('src')!==url)f.setAttribute('src',url);const status=document.querySelector('#save-state');if(status)status.textContent=S.experimentOnly?'Параметры текущего опыта · без сохранения':S.dirty?'Есть несохранённые изменения':'Сохранено в каталоге';return;}if(!S.sim)resetSimulation();const scaleLabel=document.querySelector('#view-scale');if(scaleLabel)scaleLabel.textContent=Math.round(cameraOf(m.scene).zoom*100)+'%';document.querySelector('#scene').innerHTML=sceneSVG(m,S.sim,S.history,S.present?null:S.selection);document.querySelector('#stage-time').textContent=`t = ${fmt(S.sim.t)} с`;document.querySelector('#sim-error').textContent=S.error;document.querySelector('#sim-error').classList.toggle('visible',!!S.error);let c;try{c=context(m,S.sim);}catch(e){S.error=e.message;}document.querySelector('#quantities').innerHTML=m.quantities.map(q=>`<div class="quantity"><span>${esc(q.label)}</span><strong>${c?fmt(c[q.id]):'—'} <small>${esc(q.unit)}</small></strong>${S.present?'':`<details class="measure-formula"><summary>Формула</summary><code>${esc(q.expression)}</code></details>`}</div>`).join('')+measurementCards(m,S.sim);document.querySelector('#graphs').innerHTML=(S.comparison?[]:m.graphs).map((g,i)=>`<div class="graph"><div class="graph-title"><span class="line-key" style="background:${['#4f56e8','#23a08c','#e89137','#d65b9a'][i]}"></span><strong>${esc(g.label)}</strong><span>${esc(g.unit)}</span></div>${graphSVG(m,S.history,g,i)}</div>`).join('');comparisonDraw(S);const b=document.querySelector('[data-a="play"]');if(b)b.innerHTML=icon(S.running?'pause':'play')+(S.running?'Пауза':'Запустить');const status=document.querySelector('#save-state');if(status)status.textContent=S.experimentOnly?'Параметры текущего опыта · без сохранения':S.dirty?'Есть несохранённые изменения':'Сохранено в каталоге';}
function openModel(id,present=false){S.analysisStandalone=false;dataAnalysis.reset();const m=S.library.models.find(m=>m.id===id);if(!m)return;S.comparison=null;S.lessonPhase='experiment';S.lessonAnswers={};S.scenarioNote='';S.record=structuredClone(m);S.draft=structuredClone(m.spec);S.draft.connections??=[];S.draft.fields??=[];S.sceneTool='select';S.draft.topic??=modelTopic(m.spec)==='Без темы'?'':modelTopic(m.spec);S.saveError='';S.previewError='';S.validationError='';S.controlBaseline=null;S.controlsGesture=false;S.liveEdit=null;S.folderId=m.folderId;S.selection=m.spec.bodies[0]?.id??null;S.tab=m.spec.kind==='html'?'details':S.selection?'object':'settings';S.previewUrl=null;S.previewHTML=null;S.sourceUndoPending=true;S.dirty=false;S.present=present;S.experimentOnly=present;S.view='editor';S.undo=[];S.redo=[];resetSimulation();history.replaceState(null,'',`/?model=${encodeURIComponent(id)}`);render();window.scrollTo?.(0,0);}
async function save(){if(S.busy)return false;const active=document.activeElement;if(active?.dataset?.field)commitEditorField(active);S.busy=true;S.saveError='';S.saveConflict=false;updateEditorChrome();let pending;try{if(S.draft.kind==='html'&&document.querySelector('#html-frame')?.contentWindow)await captureControls(false);pending={...snapshot(),id:S.record?.id,revision:S.record?.revision};const record=await api({action:'save',id:pending.id,spec:pending.spec,folderId:pending.folderId,expectedRevision:pending.revision});if(S.view==='editor'&&S.record?.id===pending.id){S.record=record;S.previewUrl=null;S.previewHTML=null;S.dirty=JSON.stringify(snapshot())!==JSON.stringify({spec:pending.spec,folderId:pending.folderId});if(S.dirty)saveDraft();else try{localStorage.removeItem('model-studio-public-draft');}catch{}}await refresh(true);toast(S.dirty?'Сохранена отправленная версия. Новые изменения ещё не сохранены.':'Модель сохранена');return !S.dirty;}catch(error){S.saveError=error.message;S.saveConflict=error.status===409;toast(error.message,true);saveDraft();return false;}finally{S.busy=false;render();}}
async function prepareHTMLPreview(){const html=S.draft.html,id=S.record?.id;if(S.previewHTML===html&&S.previewUrl)return;if(S.previewPendingHTML===html)return S.previewPromise;validateModel(S.draft);S.previewPendingHTML=html;S.previewPromise=(async()=>{const response=await fetch('/api/html-preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({spec:S.draft})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Не удалось открыть предварительный просмотр');if(S.draft.html===html&&S.record?.id===id){S.previewUrl=data.url;S.previewHTML=html;}})();try{await S.previewPromise;}finally{if(S.previewPendingHTML===html)S.previewPendingHTML=null;}}
function closeDialog(){document.querySelector('#dialog')?.close();document.querySelector('#modal-root').innerHTML='';}
function dialog(title,content,submitLabel=null,callback=null){closeDialog();document.querySelector('#modal-root').innerHTML=`<dialog id="dialog"><form id="dialog-form"><header><h2>${title}</h2><button type="button" class="icon-btn" data-close-dialog aria-label="Закрыть">${icon('close')}</button></header><div class="dialog-content">${content}</div>${submitLabel?`<footer><button type="button" class="btn quiet" data-close-dialog>Отмена</button><button class="btn primary" type="submit">${submitLabel}</button></footer>`:''}</form></dialog>`;const d=document.querySelector('#dialog');d.showModal();d.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',closeDialog));d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter;if(btn)btn.disabled=true;try{await callback?.(new FormData(e.target));if(document.querySelector('#dialog')===d)closeDialog();}catch(err){toast(err.message,true);if(btn)btn.disabled=false;}});}

function connectionDialog(){const m=S.draft;if(m.bodies.length<2)throw new Error('Добавьте два объекта, например опору и груз.');if((m.connections??[]).length>=80)throw new Error('Можно добавить до 80 связей');const options=m.bodies.map(b=>`<option value="${b.id}">${esc(b.name)} · ${b.id}</option>`).join('');dialog('Соединить объекты',`<p class="dialog-lead">Концы прикрепляются к центрам объектов. Опора остаётся неподвижной; свободные тела могут двигаться по силам.</p><label class="field"><span>Связь</span><select name="type">${connectionKinds.map(([type,label])=>`<option value="${type}">${label}</option>`).join('')}</select></label><label class="field"><span>Первый конец</span><select name="a">${options}</select></label><label class="field"><span>Второй конец</span><select name="b">${m.bodies.map((b,i)=>`<option value="${b.id}" ${i===1?'selected':''}>${esc(b.name)} · ${b.id}</option>`).join('')}</select></label><label class="check"><input name="activate" type="checkbox" checked>Включить движение по силам у свободных концов</label>`,'Добавить связь',async data=>{const a=m.bodies.find(b=>b.id===data.get('a')),b=m.bodies.find(b=>b.id===data.get('b'));if(a.id===b.id)throw new Error('Выберите два разных объекта');pushUndo();const link=newConnection(unique('c',m.connections??[]),a.id,b.id,data.get('type'),Math.hypot(b.x-a.x,b.y-a.y));m.connections??=[];m.connections.push(link);if(data.get('activate')&&link.type!=='line')for(const body of [a,b])if(body.motion==='fixed'&&!['anchor','platform','text','arrow'].includes(body.shape))body.motion='force';S.tab='connections';S.selection=link.id;changed();render();});}
function fieldDialog(){if((S.draft.fields??[]).length>=12)throw new Error('Можно добавить до 12 полей');dialog('Добавить поле',`<p class="dialog-lead">Поле действует на объекты с движением «По действию сил». Электрическое и магнитное поля используют заряд объекта.</p><label class="field"><span>Тип поля</span><select name="type">${fieldKinds.map(([type,label])=>`<option value="${type}">${label}</option>`).join('')}</select></label>`,'Добавить поле',async data=>{pushUndo();const f=newField(unique('field',S.draft.fields??[]),data.get('type'));S.draft.fields??=[];S.draft.fields.push(f);S.tab='fields';S.selection=f.id;changed();render();});}

function newModelDialog(){const folderId=['all','trash'].includes(S.folder)?null:S.folder,defaults=folderDefaults(S.library.folders,folderId),topic=S.topic==='all'?defaults.topic:S.topic;dialog('Новая авторская модель',`<p class="dialog-lead">Выберите конструктор объектов или HTML-модель со своей сценой и управлением.</p><label class="field"><span>Название</span><input name="title" value="Новая модель" required maxlength="120" autofocus></label><label class="field"><span>Способ создания</span><select name="kind"><option value="native">Конструктор объектов и формул</option><option value="html">Своя HTML-модель</option></select></label><label class="field"><span>Тема</span><input name="topic" list="new-topic-options" value="${esc(topic)}" maxlength="80" placeholder="Например, Кинематика"><datalist id="new-topic-options">${allTopics(S.library).map(t=>`<option value="${esc(t)}"></option>`).join('')}</datalist></label><label class="field"><span>Папка</span><select name="folder">${folderOptions(folderId)}</select></label>`,'Создать модель',async data=>{const selectedFolder=data.get('folder')||null,spec={...emptyModel(),...folderDefaults(S.library.folders,selectedFolder),title:data.get('title').trim(),topic:data.get('topic').trim()};spec.subject=topicGroups.find(group=>group.topics.includes(spec.topic))?.subject??spec.subject;if(data.get('kind')==='html'){spec.kind='html';spec.html=blankHTML.replaceAll('Моя модель',esc(spec.title));spec.previewTheme='html';}const m=await api({action:'save',spec,folderId:selectedFolder});await refresh(true);openModel(m.id);});}
function folderDialog(rename=false){const f=S.library.folders.find(f=>f.id===S.folder);dialog(rename?'Переименовать папку':'Новая папка',`<label class="field"><span>Название</span><input name="name" value="${rename?esc(f.name):''}" placeholder="Например, Урок 3 · Колебания" required maxlength="80" autofocus></label>${rename?'':`<label class="field"><span>Расположение</span><select name="parent">${folderOptions(['all','trash'].includes(S.folder)?null:S.folder,'В корне каталога')}</select></label>`}`,rename?'Сохранить':'Создать папку',async data=>{const result=await api(rename?{action:'renameFolder',id:f.id,name:data.get('name')}:{action:'createFolder',name:data.get('name'),parentId:data.get('parent')||null});if(!rename)S.folder=result.id;await refresh();});}
function modelMenu(id){const m=S.library.models.find(m=>m.id===id);dialog(esc(m.spec.title),`<div class="menu-actions">${m.archived?button('restore:'+id,'Восстановить','quiet full','reset'):`${button('open:'+id,'Открыть редактор','quiet full','edit')}${button('duplicate:'+id,'Создать копию','quiet full','copy')}${button('move:'+id,'Переместить в папку','quiet full','folder')}${button('download:'+id,'Скачать файл модели','quiet full','download')}${button('archive:'+id,'В корзину','danger full','trash')}`}</div>`);}
function exportDialog(){dialog('Экспорт модели',`<p class="dialog-lead">Сохраните редактируемый проект или готовую демонстрацию для занятия.</p><div class="menu-actions">${button('prepare-student','Подготовить опыт для ученика','primary full','book')}${button('export-json','Редактируемый проект · JSON','quiet full','download')}${button('export-html','Готовая демонстрация · HTML','quiet full','eye')}${S.draft.kind==='html'?'':button('export-png','Изображение сцены · PNG','quiet full','download')+button('export-csv','Данные опыта · CSV','quiet full','download')}${button('save-copy','Сохранить копию в каталоге','quiet full','copy')}</div>`);}
function download(name,content,type='application/json'){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportHTML(){validatePhysics(validateModel(S.draft));if(S.draft.kind==='html'){download(fileName(S.draft.title)+'.html',htmlLessonExport(S.draft,currentTheme()),'text/html;charset=utf-8');closeDialog();return;}const {standaloneHTML}=await import('./standalone.js');download(fileName(S.draft.title)+'.html',withHTMLTheme(await standaloneHTML(S.draft,await dataAnalysis.savedReport()),currentTheme()),'text/html;charset=utf-8');toast('Готовая модель сохранена. HTML работает без интернета.');closeDialog();}
async function exportPNG(){const svg=sceneExportSVG(sceneSVG(S.draft,S.sim,S.history,null)),img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=900;canvas.getContext('2d').drawImage(img,0,0,1600,900);URL.revokeObjectURL(url);canvas.toBlob(blob=>{download(fileName(S.draft.title)+'.png',blob,'image/png');closeDialog();});}
function csvExport(){const quantities=S.draft.quantities,graphs=S.draft.graphs.filter(g=>!quantities.some(q=>q.id===g.id));const cols=[...quantities,...graphs];const quote=v=>'"'+String(v).replaceAll('"','""')+'"';const lines=[['t, с',...S.draft.bodies.flatMap(b=>[`${b.name}: x, м`,`${b.name}: y, м`]),...cols.map(q=>q.label+', '+q.unit)].map(quote).join(';')];for(const s of S.history){const c=context(S.draft,s);lines.push([s.t,...S.draft.bodies.flatMap(b=>[s.bodies[b.id].x,s.bodies[b.id].y]),...cols.map(q=>evaluate(q.expression,c))].map(v=>quote(typeof v==='number'?v.toString().replace('.',','):v)).join(';'));}download(fileName(S.draft.title)+'.csv','\uFEFF'+lines.join('\r\n'),'text/csv;charset=utf-8');closeDialog();}
function help(){dialog('Создание своей модели',`<div class="help"><ol><li>Создайте модель и добавьте объект.</li><li>В свойствах выберите «По действию сил» или «По своим формулам».</li><li>Добавьте параметры: они появятся как ползунки.</li><li>Добавьте величины и графики, используя имена объектов.</li><li>Сохраните модель и включите «Показ на уроке».</li></ol><h3>Формулы</h3><p><code>+ − * / ^</code>, скобки, <code>sin cos tan sqrt abs min max pow exp log</code>. Умножение пишите явно: <code>2*x</code>. Десятичные числа в формулах — с точкой. Углы для sin и cos — в радианах.</p><p><code>t</code> — время. В формулах силы: <code>x, y, vx, vy, m</code> — состояние выбранного тела. Для обращения к другому объекту: <code>b2_x</code>, <code>b2_m</code>.</p><p>В формулах координат доступны время, параметры и начальные условия <code>x0, y0, vx0, vy0</code>. Для взаимодействий тел используйте силы.</p><h3>Связи, поля и вид</h3><p>Добавьте опору и груз, затем связь «Нить» или «Пружина». Задайте движение груза «По действию сил». В разделе «Поля» можно добавить тяжесть, электрическое и магнитное поля или сопротивление среды. Они суммируются с дополнительными силами объекта.</p><p>Колесо и кнопки +/− меняют масштаб; перетаскивание пустой сцены или режим «Переместить» сдвигает координатную плоскость. Масштаб по обеим осям одинаковый. Эти действия не меняют координаты и не сбрасывают расчёт. «Исходный вид» возвращает диапазоны из настроек. Когда сцена в фокусе, работают стрелки, +/− и 0.</p><h3>Примеры</h3><p>Тяжесть: <code>Fᵧ = -m*g</code>.<br>Пружина: <code>Fₓ = -k*(x-x0)</code>.<br>Пружина между телами по x: <code>-k*(x-b2_x-L)</code>.<br>Ток: <code>U/R</code>.<br>Движение: <code>x0+vx0*t</code>.</p><h3>Точность и ограничения</h3><p>Силы рассчитываются численно методом RK4. Шаг задаётся в настройках. Пружины создают силы между концами; нити и стержни ограничивают расстояние. При резком натяжении провисшей нити радиальная скорость гасится: это неупругое натяжение. Связи прикреплены к центрам материальных точек. Столкновения и вращение фигур пока не рассчитываются. Названия единиц — подписи автора; размерности автоматически не проверяются.</p><h3>Сохранение</h3><p>Модели сохраняются в папке data на вашем компьютере. Для обмена используйте экспорт JSON или готовую HTML-демонстрацию. При одновременной правке проверяется версия записи.</p></div>`);}
async function action(name){if(await teaching.handle(name))return;if(name.includes(':')){const [act,id]=name.split(':'),m=S.library.models.find(m=>m.id===id);closeDialog();if(act==='open')return openModel(id);if(act==='download')return download(fileName(m.spec.title)+'.json',JSON.stringify({version:1,spec:m.spec,folderName:S.library.folders.find(f=>f.id===m.folderId)?.name??null},null,2));if(act==='duplicate'){const spec=structuredClone(m.spec);delete spec.importKey;spec.title=(spec.title+' · копия').slice(0,120);const n=await api({action:'save',spec,folderId:m.folderId});await refresh(true);openModel(n.id);return;}if(act==='archive'||act==='restore'){await api({action:'archive',id,expectedRevision:m.revision,archived:act==='archive'});await refresh();toast(act==='archive'?'Модель перемещена в корзину':'Модель восстановлена');return;}if(act==='move'){dialog('Переместить модель',`<label class="field"><span>Папка</span><select name="folder">${folderOptions(m.folderId)}</select></label>`,'Переместить',async data=>{await api({action:'move',id,expectedRevision:m.revision,folderId:data.get('folder')||null});await refresh();});return;}}
 switch(name){case 'app-fullscreen':await toggleFullscreen();break;case 'app-settings':settingsDialog({document,dialog,render,introVisible:()=>!S.introHidden,setIntroVisible:value=>{S.introHidden=!value;saveCatalogPrefs();render();},navMode:()=>S.navMode,setNavMode:value=>{S.navMode=value;saveCatalogPrefs();render();}});break;case 'migrate-library':{const {migrationDialog}=await import('./migration.js');migrationDialog({document,dialog,download,hasUnsaved:()=>S.dirty&&!S.experimentOnly||dataAnalysis.hasUnsaved(),restored:async()=>{dataAnalysis.forgetStandalone();backToCatalog();S.folder='all';await refresh();}});break;}case 'prepare-student':{if(S.draft.kind==='html')await captureControls(false);const {studentDialog}=await import('./student-export.js');studentDialog({dialog,download,toast,fileName,model:()=>S.draft,theme:currentTheme,build:async model=>{validatePhysics(validateModel(model));if(model.kind==='html')return htmlLessonExport(model,currentTheme());const {standaloneHTML}=await import('./standalone.js');return withHTMLTheme(await standaloneHTML(model,await dataAnalysis.savedReport()),currentTheme());}});break;}case 'check-updates':await window.modelStudio?.checkForUpdates();break;case 'backup':{const {backupDialog}=await import('./backup.js');backupDialog({document,dialog,download,hasUnsaved:()=>S.dirty&&!S.experimentOnly||dataAnalysis.hasUnsaved(),restored:async()=>{dataAnalysis.forgetStandalone();backToCatalog();S.folder='all';await refresh();}});break;}case 'standalone-analysis':await openAnalysisWorkspace();break;case 'analysis-open':S.tab='data';S.running=false;S.present=false;S.experimentOnly=false;render();break;case 'hide-intro':case 'show-intro':S.introHidden=name==='hide-intro';saveCatalogPrefs();render();document.querySelector('[data-a="'+(S.introHidden?'show-intro':'hide-intro')+'"]')?.focus?.();break;case 'mobile-nav':S.mobileNav=!S.mobileNav;render();break;case 'reset-filters':S.search='';S.grade='all';S.topic='all';S.subject='all';updateCatalogURL();render();break;case 'capture-controls':await captureControls(true);break;case 'save-copy':{const spec=structuredClone(S.draft);delete spec.importKey;spec.title=(spec.title+' · копия').slice(0,120);const saved=await api({action:'save',spec,folderId:S.folderId});closeDialog();await refresh(true);openModel(saved.id);toast('Копия сохранена');break;}case 'refresh':return refresh();case 'new-model':return newModelDialog();case 'new-folder':return folderDialog();case 'rename-folder':return folderDialog(true);case 'delete-folder':dialog('Удалить пустую папку?',`<p>Папку можно удалить только после перемещения всех моделей и удаления вложенных папок.</p>`,'Удалить',async()=>{await api({action:'deleteFolder',id:S.folder});S.folder='all';await refresh();});break;case 'help':window.open('/guide.html','_blank','noopener');break;case 'import':document.querySelector('#import-file').click();break;case 'back':if(S.analysisStandalone){backToCatalog();break;}if(S.dirty&&!S.experimentOnly){dialog('Сохранить изменения?',`<p>Модель «${esc(S.draft.title)}» изменена. Можно сохранить её или вернуться в каталог без этих изменений.</p><div class="menu-actions">${button('save-back','Сохранить и вернуться','primary full','save')}${button('discard-back','Вернуться без сохранения','quiet full')}</div>`);return;}backToCatalog();break;case 'save-back':if(await save()){closeDialog();backToCatalog();}break;case 'discard-back':try{localStorage.removeItem('model-studio-public-draft');}catch{}closeDialog();backToCatalog();break;case 'save':await save();break;case 'present':S.present=!S.present;if(S.present&&S.tab==='data'){dataAnalysis.cancel();S.tab='settings';}if(!S.present){S.experimentOnly=false;if(S.dirty)saveDraft();}render();break;case 'play':if(S.running){S.running=false;updateScene();break;}validatePhysics(validateModel(S.draft));if(S.sim.t>=S.draft.duration)resetSimulation();S.running=true;lastFrame=performance.now();accumulator=0;updateScene();break;case 'reset':resetSimulation();updateScene();break;case 'step':S.running=false;validatePhysics(validateModel(S.draft));if(S.sim.t>=S.draft.duration)resetSimulation();{const h=Math.min(S.draft.dt,S.draft.duration-S.sim.t);comparisonStep(S,h);}recordHistory(true);updateScene();break;
 case 'scene-select':S.sceneTool='select';render();break;case 'scene-pan':S.sceneTool='pan';render();break;case 'zoom-in':changeView(zoomCamera(S.draft.scene,1.25));break;case 'zoom-out':changeView(zoomCamera(S.draft.scene,.8));break;case 'reset-view':changeView({x:(S.draft.scene.minX+S.draft.scene.maxX)/2,y:(S.draft.scene.minY+S.draft.scene.maxY)/2,zoom:1});break;
 case 'add-connection':connectionDialog();break;case 'add-field':fieldDialog();break;
 case 'duplicate-connection':case 'duplicate-field':{const list=name==='duplicate-connection'?'connections':'fields',item=S.draft[list].find(c=>c.id===S.selection);if(!item)break;pushUndo();const copy=structuredClone(item);copy.id=unique(list==='connections'?'c':'field',S.draft[list]);copy.name=(copy.name+' · копия').slice(0,80);S.draft[list].push(copy);S.selection=copy.id;changed();render();break;}
 case 'delete-connection':case 'delete-field':{const list=name==='delete-connection'?'connections':'fields';pushUndo();S.draft[list]=S.draft[list].filter(c=>c.id!==S.selection);S.selection=S.draft[list][0]?.id??null;changed();render();break;}
 case 'measure-link':{const link=S.draft.connections.find(c=>c.id===S.selection);if(!link)break;const a=S.draft.bodies.find(b=>b.id===link.a),b=S.draft.bodies.find(b=>b.id===link.b);pushUndo();link.length=Math.max(.02,Math.hypot(b.x-a.x,b.y-a.y));changed();render();break;}
 case 'add-body':dialog('Добавить объект',`<div class="palette">${objectKinds.map(([shape,label])=>`<button type="button" class="palette-item" data-add-shape="${shape}"><span class="shape-symbol ${shape}"></span>${label}</button>`).join('')}</div>`);break;
 case 'duplicate-body':{const b=S.draft.bodies.find(b=>b.id===S.selection);if(!b)break;pushUndo();const copy=structuredClone(b);copy.id=unique('b',S.draft.bodies);copy.name=(b.name+' · копия').slice(0,80);copy.x+=.5;S.draft.bodies.push(copy);S.selection=copy.id;changed();render();break;}
 case 'delete-body':pushUndo();removeBody(S.draft,S.selection);S.selection=S.draft.bodies[0]?.id??null;changed();render();break;
 case 'add-param':pushUndo();S.draft.parameters.push({id:unique('p',S.draft.parameters),label:'Новый параметр',value:1,min:0,max:10,unit:''});S.tab='parameters';changed();render();break;
 case 'add-quantity':pushUndo();S.draft.quantities.push({id:unique('q',S.draft.quantities),label:'Новая величина',expression:S.draft.bodies[0]?S.draft.bodies[0].id+'_x':'0',unit:''});S.tab='quantities';changed();render();break;
 case 'show-properties':{const pane=document.querySelector('.inspector');pane?.scrollIntoView({behavior:'smooth',block:'start'});pane?.querySelector('summary, input, select')?.focus({preventScroll:true});break;}
 case 'add-graph':if(S.draft.graphs.length>=4)throw new Error('Можно добавить до четырёх графиков');pushUndo();S.draft.graphs.push({id:unique('plot',S.draft.graphs),label:'Новый график',expression:S.draft.bodies[0]?S.draft.bodies[0].id+'_x':'t',unit:''});S.tab='graphs';changed();render();break;
 case 'undo':if(S.undo.length){S.redo.push(historySnapshot());const old=S.undo.pop();S.draft=old.spec;S.folderId=old.folderId;S.sourceUndoPending=true;S.liveEdit=null;S.controlsGesture=false;S.selection=[...S.draft.bodies,...(S.draft.connections??[]),...(S.draft.fields??[])].some(b=>b.id===S.selection)?S.selection:(S.draft[S.tab]?.[0]?.id??S.draft.bodies[0]?.id??null);changed();applySavedControls();render();}break;
 case 'redo':if(S.redo.length){S.undo.push(historySnapshot());const next=S.redo.pop();S.draft=next.spec;S.folderId=next.folderId;S.sourceUndoPending=true;S.liveEdit=null;S.controlsGesture=false;S.selection=[...S.draft.bodies,...(S.draft.connections??[]),...(S.draft.fields??[])].some(b=>b.id===S.selection)?S.selection:(S.draft[S.tab]?.[0]?.id??S.draft.bodies[0]?.id??null);changed();applySavedControls();render();}break;
 case 'html-export':await exportHTML();break;case 'html-preview':try{S.previewError='';await prepareHTMLPreview();S.sourceUndoPending=true;S.tab='details';render();}catch(error){S.previewError=error.message;updateEditorChrome();}break;case 'export':exportDialog();break;case 'export-json':download(fileName(S.draft.title)+'.json',JSON.stringify({version:1,spec:S.draft},null,2));closeDialog();break;case 'export-html':await exportHTML();break;case 'export-csv':csvExport();break;case 'export-png':await exportPNG();break;case 'recover-draft':{const draft=JSON.parse(localStorage.getItem('model-studio-public-draft'));if(draft.id&&S.library.models.some(m=>m.id===draft.id))openModel(draft.id);else {S.draft=emptyModel();S.record=null;S.view='editor';}if(S.record&&draft.id===S.record.id)S.record.revision=Number.isInteger(draft.revision)?draft.revision:-1;S.draft=draft.spec;S.folderId=draft.folderId;S.dirty=true;S.selection=S.draft.bodies[0]?.id;S.tab=S.draft.kind==='html'?'source':'settings';S.previewUrl=null;resetSimulation();closeDialog();render();break;}
 }}
function backToCatalog(){if(S.analysisStandalone)dataAnalysis.remember();S.analysisStandalone=false;dataAnalysis.reset();S.running=false;S.view='catalog';S.present=false;updateCatalogURL();refresh().then(()=>window.scrollTo?.(0,0));}
let pendingEditorButton=null;
function flushFieldRender(){if(S.fieldRenderPending&&S.view==='editor')render();}
document.addEventListener('pointerdown',e=>{pendingEditorButton=e.target.closest?.('button')??null;},true);
document.addEventListener('pointerup',()=>{setTimeout(()=>{pendingEditorButton=null;flushFieldRender();},0);},true);
document.addEventListener('pointercancel',()=>{pendingEditorButton=null;flushFieldRender();},true);
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;try{if(target.dataset.a)return await action(target.dataset.a);if(target.dataset.toggleFolder){const id=target.dataset.toggleFolder;S.expanded.has(id)?S.expanded.delete(id):S.expanded.add(id);saveCatalogPrefs();render();return;}if(target.dataset.navMode){S.navMode=target.dataset.navMode;saveCatalogPrefs();render();return;}if(target.dataset.topicNav){S.mobileNav=false;S.folder='all';S.grade='all';S.search='';S.topic=target.dataset.topicNav;S.navMode='topics';updateCatalogURL();render();return;}if(target.dataset.topic){S.topic=target.dataset.topic;updateCatalogURL();render();return;}if(target.dataset.folder){navigateFolder(target.dataset.folder);return;}if(target.dataset.subject){S.subject=target.dataset.subject;S.grade='all';updateCatalogURL();render();return;}if(target.dataset.grade){S.grade=target.dataset.grade;updateCatalogURL();render();return;}if(target.dataset.open)return openModel(target.dataset.open,true);if(target.dataset.cardMenu)return modelMenu(target.dataset.cardMenu);if(target.dataset.selectComponent){const [tab,id]=target.dataset.selectComponent.split(':');S.tab=tab;S.selection=id;render();return;}if(target.dataset.tab){S.tab=target.dataset.tab;if(S.tab==='data')S.running=false;else dataAnalysis.cancel?.();if(['connections','fields'].includes(S.tab))S.selection=S.draft[S.tab]?.[0]?.id??null;S.sourceUndoPending=true;render();return;}if(target.dataset.selectBody){S.selection=target.dataset.selectBody;S.tab='object';render();return;}if(target.dataset.addShape){pushUndo();if(S.draft.bodies.length>=60)throw new Error('Можно добавить до 60 объектов');const b=newBody(unique('b',S.draft.bodies),target.dataset.addShape);const camera=cameraOf(S.draft.scene);b.x=camera.x;b.y=camera.y;if(!['anchor','platform','text','arrow'].includes(b.shape))b.motion='force';S.draft.bodies.push(b);S.selection=b.id;S.tab='object';changed();closeDialog();render();return;}if(target.dataset.remove){const [list,index]=target.dataset.remove.split(':');pushUndo();const removed=S.draft[list].splice(Number(index),1)[0];if(list==='connections')for(const p of S.draft.parameters)if(p.binding?.connection===removed.id)delete p.binding;if(list==='parameters'){for(const scenario of S.draft.scenarios??[])if(scenario.parameters)delete scenario.parameters[removed.id];}changed();render();}}catch(err){toast(err.message,true);}finally{pendingEditorButton=null;flushFieldRender();}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset?.lessonAnswer){S.lessonAnswers??={};S.lessonAnswers[t.dataset.lessonAnswer]=t.value;return;}if(t.id==='html-source'){if(S.sourceUndoPending){pushUndo();S.sourceUndoPending=false;}S.draft.html=t.value;S.previewError='';S.saveError='';S.previewUrl=null;S.previewHTML=null;S.dirty=true;saveDraft();const status=document.querySelector('#save-state');if(status)status.textContent='Есть несохранённые изменения';return;}if(t.id==='search'){S.search=t.value;updateCatalogResults();return;}if(t.dataset.live){if(S.liveEdit!==t.dataset.live){pushUndo();S.liveEdit=t.dataset.live;}const p=S.draft.parameters.find(p=>p.id===t.dataset.live);p.value=Number(t.value);applyBindings(S.draft);S.comparison=null;S.dirty=true;resetSimulation();saveDraft();document.querySelector('#value-'+p.id).textContent=fmt(p.value)+' '+p.unit;updateScene();updateEditorChrome();}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.fieldLayer){pushUndo();S.draft.scene.fieldLayers??={};S.draft.scene.fieldLayers[t.dataset.fieldLayer]=t.checked;S.dirty=true;saveDraft();updateScene();updateEditorChrome();return;}if(t.dataset.gravitySource){const b=S.draft.bodies.find(b=>b.id===t.dataset.gravitySource);if(!b)return;pushUndo();b.gravityEnabled=t.checked;changed();render();return;}if(t.dataset.chargeSource){const b=S.draft.bodies.find(b=>b.id===t.dataset.chargeSource);if(!b)return;pushUndo();b.fieldEnabled=t.checked;changed();render();return;}if(t.dataset.fieldAll!==undefined||t.dataset.fieldTarget!==undefined){const index=Number(t.dataset.fieldAll??t.dataset.fieldTarget),f=S.draft.fields[index];if(!f)return;pushUndo();if(t.dataset.fieldAll!==undefined){f.all=t.checked;f.targets=t.checked?[]:S.draft.bodies.map(b=>b.id);}else{if(f.all){f.all=false;f.targets=S.draft.bodies.map(b=>b.id);}f.targets=t.checked?[...new Set([...f.targets,t.dataset.bodyTarget])]:f.targets.filter(id=>id!==t.dataset.bodyTarget);}changed();render();return;}if(t.id==='topic-filter'){S.topic=t.value;updateCatalogURL();render();return;}if(t.id==='sort-models'){S.sort=t.value;updateCatalogURL();render();return;}if(t.dataset.live){S.liveEdit=null;return;}if(t.id==='speed'){const value=Number(t.value);if(Number.isFinite(value)&&value>=.01&&value<=20)S.speed=value;return;}if(t.id==='editor-folder'){pushUndo();S.folderId=t.value||null;S.dirty=true;saveDraft();updateEditorChrome();return;}commitEditorField(t);});
document.querySelector('#import-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>16*1024*1024)throw new Error('Файл модели слишком большой');const raw=await file.text();let input;if(/\.html?$/i.test(file.name)){const title=raw.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]?.replace(/<[^>]*>/g,'').trim();input={...emptyModel(),kind:'html',html:raw,title:(title||file.name.replace(/\.html?$/i,'')).slice(0,120),description:'Импортированная интерактивная модель',sourceName:file.name,previewTheme:'html',...folderDefaults(S.library.folders,S.folder)};}else input=JSON.parse(raw);const spec=validatePhysics(validateModel(input.spec??input));const record=await api({action:'save',spec,folderId:['all','trash'].includes(S.folder)?null:S.folder});await refresh(true);openModel(record.id);toast('Модель импортирована');}catch(err){toast(err.message,true);}finally{e.target.value='';}});

function saveCatalogPrefs(){try{localStorage.setItem('model-studio-public-catalog-prefs',JSON.stringify({navMode:S.navMode,expanded:[...S.expanded],introHidden:S.introHidden}));}catch{}}
function updateCatalogURL(){const query=new URLSearchParams();if(S.folder!=='all')query.set('folder',S.folder);if(S.topic!=='all')query.set('topic',S.topic);if(S.grade!=='all')query.set('grade',S.grade);if(S.subject!=='all')query.set('subject',S.subject);if(S.search)query.set('search',S.search);if(S.sort!=='recent')query.set('sort',S.sort);history.replaceState(null,'','/'+(query.size?'?'+query.toString():''));}
function navigateFolder(id){S.mobileNav=false;S.folder=id;S.topic='all';S.grade='all';S.search='';if(!['all','trash'].includes(id)){S.navMode='folders';for(const f of folderPath(S.library.folders,id))S.expanded.add(f.id);}saveCatalogPrefs();updateCatalogURL();render();}
function updateCatalogResults(){const models=visibleModels(),grid=document.querySelector('#model-grid');if(grid){grid.className=S.sort==='topic'?'grouped-models':'model-grid';grid.innerHTML=groupedCards(models,S,cards);}for(const key of ['#catalog-count','#filter-summary']){const node=document.querySelector(key);if(node)node.textContent=models.length+' '+plural(models.length);}updateCatalogURL();}
function updateEditorChrome(){if(S.view!=='editor')return;const status=document.querySelector('#save-state');if(status)status.textContent=S.busy?'Сохраняем…':S.experimentOnly?'Параметры текущего опыта · без сохранения':S.dirty?'Есть несохранённые изменения':'Сохранено в каталоге';const title=document.querySelector('.editor-identity strong');if(title)title.textContent=S.draft.title;const feedback=document.querySelector('#editor-feedback');if(feedback){const message=S.saveError||S.previewError||S.validationError;feedback.classList.toggle('visible',!!message);feedback.innerHTML=message?'<span>'+esc(message)+'</span>'+(S.saveConflict?button('save-copy','Сохранить копию','quiet','copy'):''):'';}for(const [act,disabled]of [['save',S.busy],['undo',!S.undo.length],['redo',!S.redo.length]]){const node=document.querySelector('[data-a="'+act+'"]');if(node)node.disabled=disabled;}}
async function captureControls(showToast=false){const frame=document.querySelector('#html-frame'),draft=S.draft,html=draft.html;if(!frame?.contentWindow)return;const controls=await requestModelControls(frame);if(S.view!=='editor'||S.draft!==draft||S.draft.html!==html)return;if(JSON.stringify(controls)!==JSON.stringify(S.draft.initialControls??[])){pushUndo();S.draft.initialControls=controls;S.dirty=true;saveDraft();updateEditorChrome();}if(showToast)toast('Начальные параметры запомнены. Нажмите «Сохранить».');}
function commitEditorField(t){const key=t.dataset?.field;if(!key||S.view!=='editor')return;const value=t.type==='checkbox'?t.checked:t.type==='number'?Number(t.value.replace(',','.')):t.value;let obj,prop;if(key.startsWith('body.')){obj=S.draft.bodies.find(b=>b.id===S.selection);prop=key.slice(5);}else{const parts=key.split('.');obj=S.draft;for(const part of parts.slice(0,-1))obj=obj?.[part];prop=parts.at(-1);}if(!obj||obj[prop]===value)return;if(prop==='id'){const occupied=[...S.draft.bodies,...S.draft.parameters,...S.draft.quantities,...(S.draft.connections??[]),...(S.draft.fields??[])].some(item=>item!==obj&&item.id===value);if(!/^[A-Za-z][A-Za-z0-9_]{0,39}$/.test(value)||reservedNames.has(value)||occupied){t.value=obj[prop];toast('Имя должно быть уникальным: латинская буква, затем буквы, цифры или _.',true);return;}}pushUndo();if(prop==='id'&&!key.startsWith('graphs.'))renameReferences(S.draft,obj.id,value,key.startsWith('body.'));obj[prop]=value;if(key.startsWith('body.'))for(const p of S.draft.parameters)if(p.binding?.body===obj.id&&p.binding.property===prop){p.value=value;p.min=Math.min(p.min,value);p.max=Math.max(p.max,value);}if(/^connections\.\d+\.length$/.test(key))for(const p of S.draft.parameters)if(p.binding?.connection===obj.id){p.value=value;p.min=Math.min(p.min,value);p.max=Math.max(p.max,value);applyBindings(S.draft);}if(prop==='name'){const heading=document.querySelector('.selected-object-name');if(heading)heading.textContent=value;const selector=key.startsWith('body.')?'[data-select-body="'+obj.id+'"]':'[data-select-component="'+key.split('.')[0]+':'+obj.id+'"]';const label=document.querySelector(selector)?.querySelector(':scope > span:last-child');if(label?.firstChild)label.firstChild.textContent=value;}if(key==='body.motion'&&value!=='fixed'&&obj.gravityRadius>0){obj.gravityRadius=0;toast('Движущийся источник считается точечным: радиус шара сброшен до 0.');}if(prop==='autoScale'&&value===false){obj.minY??=0;obj.maxY??=1;}if(prop==='type'&&value==='magnetic-gradient')for(const [k,v]of Object.entries(newField('template',value)))if(obj[k]===undefined)obj[k]=v;if(key==='body.id')S.selection=value;changed();if(['body.motion','body.shape','body.id','body.charge','body.fieldEnabled','body.gravityEnabled'].includes(key)||key.endsWith('.type')||key.endsWith('.autoScale')){if(pendingEditorButton)S.fieldRenderPending=true;else render();}else{if(key.startsWith('parameters.')){const controls=document.querySelector('#live-controls');if(controls)controls.innerHTML=liveControls();}updateScene();updateEditorChrome();}}
document.addEventListener('keydown',async event=>{if(!(event.ctrlKey||event.metaKey))return;if(S.view==='analysis'&&event.key.toLowerCase()==='s'){event.preventDefault();try{await dataAnalysis.saveStandalone();}catch(error){toast(error.message,true);}return;}if(S.view!=='editor')return;const key=event.key.toLowerCase();try{if(key==='s'){event.preventDefault();await save();}else if(!event.target.closest?.('input,textarea,select,[contenteditable=true]')&&(key==='z'||key==='y')){event.preventDefault();await action(key==='y'||event.shiftKey?'redo':'undo');}}catch(error){toast(error.message,true);}});
function applySavedControls(){if(S.draft.kind==='html')document.querySelector('#html-frame')?.contentWindow?.postMessage({type:'model-studio-apply-controls',controls:S.draft.initialControls??S.controlBaseline??[]},'*');}
document.addEventListener('focusout',event=>{if(S.view==='editor'&&event.target.dataset?.field)commitEditorField(event.target);});
window.addEventListener('message',event=>{const frame=document.querySelector('#html-frame');if(S.view!=='editor'||!frame?.contentWindow||event.source!==frame.contentWindow)return;if(event.data?.type==='model-studio-theme-ready'){S.controlsGesture=false;try{S.controlBaseline=structuredClone(validateControls(event.data.baseline??[]));}catch{}return;}if(event.data?.type==='model-studio-controls-changed'){try{const controls=validateControls(event.data.controls);if(JSON.stringify(controls)!==JSON.stringify(S.draft.initialControls??S.controlBaseline)){if(!S.controlsGesture)pushUndo();S.controlsGesture=true;S.draft.initialControls=structuredClone(controls);S.dirty=true;S.saveError='';saveDraft();updateEditorChrome();}if(event.data.phase==='change')S.controlsGesture=false;}catch{}return;}if(event.data?.type!=='model-studio-error')return;const line=Number(event.data.line);S.previewError=String(event.data.message||'Ошибка сценария').slice(0,800)+(Number.isFinite(line)&&line>0?' · строка документа предпросмотра '+line:'');updateEditorChrome();});

let disposeViewport=null;
function bindNativeScene(){const header=document.querySelector('.editor-header');if(header?.getBoundingClientRect&&app.style)app.style.setProperty('--editor-header-height',header.getBoundingClientRect().height+'px');disposeViewport?.();const element=document.querySelector('#scene');if(!element)return;disposeViewport=installSceneNavigation(element,{getModel:()=>S.draft,getMode:()=>S.sceneTool,canEditBody:()=>!S.present&&!S.running,onGestureStart:()=>pushUndo(),onViewChange:camera=>changeView(camera,false),onBodyChange:(id,x,y)=>{const b=S.draft.bodies.find(b=>b.id===id);if(!b)return;if(S.draft.geometry?.some(g=>g.target===id)){toast('Это зависимая точка. Измените параметр ограничения.');return;}b.x=Math.round(x*1000)/1000;b.y=Math.round(y*1000)/1000;S.comparison=null;for(const p of S.draft.parameters)if(p.binding?.body===id&&['x','y'].includes(p.binding.property)){p.value=b[p.binding.property];p.min=Math.min(p.min,p.value);p.max=Math.max(p.max,p.value);}S.dirty=true;S.saveError='';resetSimulation();updateScene();updateEditorChrome();},onGestureEnd:kind=>{saveDraft();if(kind==='body')render();else updateEditorChrome();},onLabelChange:(id,x,y)=>{const b=S.draft.bodies.find(b=>b.id===id);if(!b)return;b.labelOffset={x:Math.max(-500,Math.min(500,x)),y:Math.max(-500,Math.min(500,y))};S.dirty=true;updateScene();updateEditorChrome();},onSelect:(kind,id)=>{S.selection=id;S.tab=kind==='connection'?'connections':'object';render();}});}
let lastFrame=0,accumulator=0,lastPaint=0;
function recordHistory(force=false){if(force||!S.history.length||S.sim.t-S.history.at(-1).t>=Math.max(.025,S.draft.duration/1400)){S.history.push(structuredClone(S.sim));if(S.history.length>1600)S.history.shift();}}
function frame(now){if(S.running&&S.view==='editor'){accumulator+=Math.min((now-lastFrame)/1000,.1)*S.speed;let count=0;try{while(accumulator>=S.draft.dt&&count++<200&&S.sim.t<S.draft.duration-1e-9){const h=Math.min(S.draft.dt,S.draft.duration-S.sim.t);comparisonStep(S,h);accumulator-=h;recordHistory();}if(S.sim.t>=S.draft.duration-1e-9){S.running=false;recordHistory(true);}if(now-lastPaint>32||!S.running){updateScene();lastPaint=now;}}catch(e){S.error=e.message;S.running=false;updateScene();}}lastFrame=now;requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{if(document.hidden){S.running=false;updateScene();}});
window.addEventListener('resize',()=>{if(S.view==='editor'&&S.draft.kind!=='html'){const header=document.querySelector('.editor-header');if(header?.getBoundingClientRect&&app.style)app.style.setProperty('--editor-header-height',header.getBoundingClientRect().height+'px');}});
window.addEventListener('beforeunload',e=>{if((S.dirty&&!S.experimentOnly&&S.view==='editor')||dataAnalysis.hasUnsaved()){e.preventDefault();e.returnValue='';}});
await refresh();if(!['all','trash'].includes(S.folder)&&!S.library.folders.some(f=>f.id===S.folder)){S.folder='all';render();}const modelId=new URLSearchParams(location.search).get('model');if(modelId)openModel(modelId,true);else if(new URLSearchParams(location.search).has('analysis'))openAnalysisWorkspace();try{if(localStorage.getItem('model-studio-public-draft')&&!modelId&&!S.analysisStandalone)dialog('Есть незавершённая работа',`<p>В редакторе остались несохранённые изменения. Хотите продолжить?</p><div class="menu-actions">${button('recover-draft','Продолжить редактирование','primary full')}</div>`);}catch{}requestAnimationFrame(frame);

initAppSettings();
if(window.modelStudio)initDesktopUpdates();
